const err = $json;

const nombreWorkflow = err.workflow ? err.workflow.name : 'desconocido';
const nodoFallido = err.execution && err.execution.error && err.execution.error.node
  ? err.execution.error.node.name
  : (err.trigger && err.trigger.node) || 'desconocido';
const mensajeError = (err.execution && err.execution.error && err.execution.error.message)
  || (err.execution && err.execution.lastNodeExecuted)
  || JSON.stringify(err).slice(0, 500);
const urlEjecucion = err.execution ? err.execution.url : null;

const texto = [
  `Workflow: ${nombreWorkflow}`,
  `Nodo: ${nodoFallido}`,
  `Error: ${mensajeError}`,
  urlEjecucion ? `Ejecución: ${urlEjecucion}` : null,
].filter(Boolean).join('\n');

return { json: { asunto: `⚠️ Radar de empleos — falló ${nombreWorkflow}`, texto } };
